 const bounds=inkBounds(plan.items,m,s.pen);$('paperPlacement').textContent=bounds?`امتداد الحبر: ${paperPair(bounds.width,bounds.height)} مم · هامش ${mm(s.margin)} مم · قلم ${mm(s.pen)} مم`:'لا توجد خطوط مختارة على الورقة.';
