function fitPaperPreview(){const sheet=$('paperSheet');if($('paperPreview').hidden||sheet.hidden||!mapping)return;const box=sheet.parentElement,style=getComputedStyle(box),width=box.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),height=box.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom),ratio=mapping.paperWidth/mapping.paperHeight;if(width<=0||height<=0)return;const w=Math.min(width,height*ratio);sheet.style.width=w+'px';sheet.style.height=w/ratio+'px';}
